// Grammar spine for Fluidez 2. Order within a unit = order of Introduce days.
// u = unit number; pb = band the PCIC (or PCIC-aligned programmes) gives it;
// placement becomes 'teaching_choice' whenever the course band differs from pb.
// Fields: id, u, t (learner-facing title), es, en, pb, pcic, req, src, note
module.exports = [
// ---------------- A1 ----------------
// u01 Hello, who I am
{id:'g:ser-identity',u:1,t:'Saying who you are and where you\'re from',es:'Soy Tomás. Soy de Toronto. ¿Y tú, de dónde eres?',en:'I\'m Tomás. I\'m from Toronto. And you, where are you from?',pb:'A1',pcic:['gramatica:12.1','gramatica:12.2.1'],req:[],src:['ser-estar','dlg-presentarse','nt-origen-a1','gr-atributo-a1','fn-identificar-a1']},
{id:'g:sounds-letters',u:1,t:'Reading Spanish aloud: five vowels, the letters that surprise you, and the stress mark',es:'café, mamá, teléfono, perro / pero, jugo, calle',en:'',pb:'A1',pcic:['pronunciacion','ortografia'],req:[],src:['gr-sonidos-a1','gr-acentuacion-a1','dc-entonacion-a1'],note:'Text-only: describe sounds against English; teach the written accent as a typing skill the checker will hold them to.'},
{id:'g:gender-articles',u:1,t:'Every noun is "el" or "la": the, a, and how to guess which',es:'el café, la mesa, un carro, una ciudad, el día, la mano',en:'the coffee, the table, a car, a city, the day, the hand',pb:'A1',pcic:['gramatica:1.2','gramatica:3.1','gramatica:3.2'],req:[],src:['gender-articles','gr-genero-sustantivos-a1','gr-articulo-indefinido-a1','gr-masculino-a2'],note:'Flag el día, la mano, el problema, la foto. Always teach nouns with their article from here on.'},
{id:'g:present-ar',u:1,t:'Talking about what you do: -ar verbs (hablo, hablas, habla)',es:'Trabajo en un café. ¿Hablas inglés? Vale cocina muy bien.',en:'I work in a café. Do you speak English? Vale cooks very well.',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:ser-identity'],src:['presente','gr-presente-indicativo-valores-a1'],note:'Ustedes forms only; vosotros never produced.'},
// u02 My day-to-day
{id:'g:present-er-ir',u:2,t:'The other regular verbs: -er and -ir (como, vivo)',es:'Vivo en Bogotá. Comemos a la una. ¿Lees en español?',en:'I live in Bogotá. We eat at one. Do you read in Spanish?',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:present-ar'],src:['presente']},
{id:'g:estar-location-states',u:2,t:'Where something is and how someone is: estar',es:'El café está en La Candelaria. ¿Cómo estás? Estoy cansado.',en:'The café is in La Candelaria. How are you? I\'m tired.',pb:'A1',pcic:['gramatica:12.1','gramatica:9.1.1'],req:['g:ser-identity'],src:['ser-estar','nt-localizacion-a1','gr-nucleo-verbal-a1'],note:'Only location and a small set of states (bien, mal, cansado, enfermo, feliz). ser vs estar with adjectives comes at A2 (g:ser-estar-adjectives).'},
{id:'g:questions',u:2,t:'Asking questions: qué, quién, dónde, cuándo, cómo, cuánto, por qué',es:'¿Dónde vives? ¿Cuántos años tienes? ¿Por qué estás aquí?',en:'Where do you live? How old are you? Why are you here?',pb:'A1',pcic:['gramatica:7.3','gramatica:8.8'],req:['g:present-er-ir'],src:['gr-interrogativos-a1','dc-entonacion-a1','fn-pedir-informacion-a1'],note:'¿ ? marks, accents on question words, intonation questions (¿Tienes hambre?).'},
// u03 Likes, wants and plans
{id:'g:gustar-basic',u:3,t:'Saying what you like: me gusta, me gustan, ¿te gusta?',es:'Me gusta el café. No me gustan los lunes. ¿Te gusta bailar?',en:'I like coffee. I don\'t like Mondays. Do you like dancing?',pb:'A1',pcic:['gramatica:12.1','gramatica:7.1.3'],req:['g:gender-articles','g:present-ar'],src:['gr-verbos-predicativos-tipos-a2','fn-preguntar-gustos-a2','fn-expresar-gustos-a2','task-gustos'],note:'Unpacks c:me-gusta. Only me/te here; le/les/nos and encantar/doler in g:gustar-full.'},
{id:'g:stem-boot',u:3,t:'Verbs that change inside: quiero, puedo, prefiero, duermo (the "boot" verbs)',es:'¿Quieres un tinto? No puedo hoy. Prefiero el té. Duermo poco.',en:'Do you want a coffee? I can\'t today. I prefer tea. I sleep little.',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:present-er-ir'],src:['gr-presente-irregular-a2','presente'],note:'e→ie and o→ue (and jugar u→ue). Unpacks c:quiero and c:puedo. e→i comes later (g:stem-e-i).'},
{id:'g:ir-a-plans',u:3,t:'Talking about plans: voy a + verb',es:'Voy a abrir el café el lunes. ¿Qué vas a hacer mañana?',en:'I\'m going to open the café on Monday. What are you going to do tomorrow?',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:present-er-ir'],src:['gr-ir-a-infinitivo-a1','gr-infinitivo-usos-a1','fn-expresar-planes-b1'],note:'Unpacks c:voy-a. Ir a is THE future of everyday Latin American Spanish; the -ré future is taught later for guesses and promises.'},
// u04 The weekend (checkpoint)
{id:'g:preterite-ar',u:4,t:'Saying what you did: -ar verbs in the past (hablé, hablaste, habló)',es:'Ayer trabajé hasta las nueve. ¿Compraste el pan? Vale cerró temprano.',en:'Yesterday I worked until nine. Did you buy the bread? Vale closed early.',pb:'A2',pcic:['gramatica:9.1.3'],req:['g:present-ar'],src:['preterito','gr-preterito-indefinido-a2','task-a2-ayer'],note:'LatAm: the preterite is THE past, including for today (Hoy trabajé mucho). Unpacks c:compre-trabaje.'},
{id:'g:preterite-er-ir',u:4,t:'The past of -er and -ir verbs (comí, viviste, salió)',es:'Comí arepas. ¿Saliste anoche? Simón aprendió una palabra nueva.',en:'I ate arepas. Did you go out last night? Simón learned a new word.',pb:'A2',pcic:['gramatica:9.1.3'],req:['g:preterite-ar','g:present-er-ir'],src:['preterito','gr-preterito-indefinido-a2'],note:'Unpacks c:comi.'},
{id:'g:preterite-ser-ir-hacer',u:4,t:'The three past forms you\'ll use most: fui, fue, hice',es:'Fui al mercado. Fue un desastre. ¿Qué hiciste el sábado?',en:'I went to the market. It was a disaster. What did you do on Saturday?',pb:'A2',pcic:['gramatica:9.1.3'],req:['g:preterite-er-ir'],src:['preterito','gr-indefinido-irregular-a2'],note:'fui = I went AND I was; context decides. Unpacks c:fui and c:que-hiciste.'},
// u05 People in my life
{id:'g:yo-irregular',u:5,t:'Verbs with an odd "I" form: tengo, hago, salgo, conozco, sé',es:'Tengo dos hermanos. Salgo a las seis. No conozco a nadie aquí. No sé.',en:'I have two brothers. I leave at six. I don\'t know anyone here. I don\'t know.',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:stem-boot'],src:['gr-presente-yo-irregular-a1','gr-presente-irregular-a2'],note:'Unpacks c:tengo and c:no-se. tener also e→ie (tienes, tiene).'},
{id:'g:adjective-agreement',u:5,t:'Describing people and things: alto/alta, simpáticos, inteligente',es:'Mi hermana es alta y muy simpática. Los buñuelos están deliciosos.',en:'My sister is tall and very nice. The buñuelos are delicious.',pb:'A1',pcic:['gramatica:2.2','gramatica:2.3','gramatica:1.3','gramatica:10.3'],req:['g:gender-articles'],src:['gr-genero-adjetivo-a1','gr-adjetivos-calificativos-a1','gr-numero-sustantivos-a1','gn-describir-persona-a1'],note:'Plurals of nouns and adjectives together; adjective after the noun by default.'},
{id:'g:possessives',u:5,t:'Whose is it: mi, tu, su, nuestro',es:'Mi abuela tenía un café. ¿Tu hermana vive en Medellín? Su perro es enorme.',en:'My grandmother had a café. Does your sister live in Medellín? His dog is huge.',pb:'A1',pcic:['gramatica:5'],req:['g:adjective-agreement'],src:['gr-posesivos-forma-a1','gr-posesivos-distribucion-a1','nt-familia-a1'],note:'su = his/her/their/your (usted); disambiguate with de él / de ella.'},
// u06 How it was
{id:'g:imperfect-states',u:6,t:'Setting the scene in the past: era, estaba, tenía, había',es:'El café era pequeño. Había una mesa al lado de la ventana. Mi abuela tenía sesenta años.',en:'The café was small. There was a table by the window. My grandmother was sixty.',pb:'A2',pcic:['gramatica:9.1.2'],req:['g:preterite-ser-ir-hacer','g:estar-location-states'],src:['gr-imperfecto-estados-a1','imperfecto'],note:'Only state verbs (ser, estar, tener, haber, querer, saber, poder). Full imperfect at g:imperfect-habitual. Unpacks c:era.'},
{id:'g:preterite-irregular-strong',u:6,t:'Irregular pasts: tuve, estuve, pude, puse, vine, quise, dije, traje',es:'Tuve que salir. Estuvimos dos horas en el trancón. No pude dormir. ¿Qué te dijo?',en:'I had to leave. We were in the traffic jam for two hours. I couldn\'t sleep. What did he tell you?',pb:'A2',pcic:['gramatica:9.1.3'],req:['g:preterite-ser-ir-hacer'],src:['gr-indefinido-irregular-a2','preterito'],note:'Teach the shared endings (-e, -iste, -o, -imos, -ieron; dijeron/trajeron). Includes dar/ver.'},
{id:'g:hace-ago',u:6,t:'How long ago: hace + time',es:'Llegué hace dos semanas. Mi abuela abrió el café hace cuarenta años.',en:'I arrived two weeks ago. My grandmother opened the café forty years ago.',pb:'A2',pcic:['gramatica:9.1.3','nociones_generales'],req:['g:preterite-ar'],src:['nt-localizacion-tiempo-a2','dc-deixis-temporal-a2'],note:'Also hace + time + que + present (Hace un mes que vivo aquí) as a frame.'},
// u07 Where I live
{id:'g:hay-vs-esta',u:7,t:'"There is" vs "it\'s there": hay un banco / el banco está…',es:'Hay una panadería en la esquina. La panadería está al lado del café.',en:'There\'s a bakery on the corner. The bakery is next to the café.',pb:'A1',pcic:['gramatica:12.1','nociones_generales'],req:['g:estar-location-states','g:gender-articles'],src:['nt-existencia-a1','nt-existencia-inexistencia-a2','gn-describir-lugar-a1'],contrasts:['x:hay-esta'],note:'hay + un/una/numbers/nothing; está/están + el/la/names. hay is never plural (hay dos).'},
{id:'g:demonstratives',u:7,t:'This, that, that one over there: este, ese, aquel (and esto, eso)',es:'Este apartamento es caro. ¿Y ese? ¿Qué es eso?',en:'This apartment is expensive. And that one? What is that?',pb:'A1',pcic:['gramatica:4'],req:['g:adjective-agreement'],src:['gr-demostrativos-distribucion-a1','gr-demostrativos-a2','dc-deixis-espacial-a1'],note:'ese covers most "that" in speech; aquel for far away and far back in time.'},
{id:'g:quantifiers',u:7,t:'How much and how many: mucho, poco, bastante, demasiado — and muy vs mucho',es:'Hay mucha gente. El arriendo es muy caro. Tengo demasiadas cosas.',en:'There are a lot of people. The rent is very expensive. I have too many things.',pb:'A1',pcic:['gramatica:6.1'],req:['g:adjective-agreement'],src:['gr-cuantificadores-no-universales-a1','nt-cantidad-relativa-a1','gr-cuantificadores-a2'],contrasts:['x:muy-mucho']},
// u08 Have you ever…? (checkpoint)
{id:'g:perfecto-experience',u:8,t:'Have you ever…? Experience and "not yet": he estado, todavía no he…',es:'¿Has estado en Cartagena? Nunca he probado el ajiaco. Todavía no he visto el contrato.',en:'Have you been to Cartagena? I\'ve never tried ajiaco. I haven\'t seen the contract yet.',pb:'A2',pcic:['gramatica:9.1.6','gramatica:9.4.3'],req:['g:preterite-ser-ir-hacer'],src:['gr-preterito-perfecto-a2','perfecto','gr-participio-adjetival-a1','task-a2-experiencia','nt-anterioridad-a2'],note:'LatAm scope ONLY: life experience (alguna vez, nunca), ya / todavía no, and situations still open. Never for finished events today: Hoy fui al banco, not Hoy he ido. Unpacks c:has-estado.'},
{id:'g:negation-words',u:8,t:'Saying no to everything: nada, nadie, nunca, tampoco, ningún',es:'No hay nadie. No como nunca carne. —No tengo hambre. —Yo tampoco.',en:'There\'s nobody. I never eat meat. —I\'m not hungry. —Me neither.',pb:'A1',pcic:['gramatica:6.1','gramatica:8.2','gramatica:13.3'],req:['g:present-er-ir'],src:['gr-adverbios-afirmacion-negacion-a1','gr-indefinidos-negativos-b1','dc-negacion-a1','dc-negacion-refuerzo-a2'],note:'Double negative is required (no… nada). también/tampoco.'},
{id:'g:verb-infinitive',u:8,t:'Verb + verb: puedo ir, sé nadar, necesito dormir, pienso volver',es:'¿Sabes manejar? Necesito descansar. Pienso volver en diciembre.',en:'Can you drive? I need to rest. I\'m planning to come back in December.',pb:'A1',pcic:['gramatica:9.4.1','gramatica:15.1.1'],req:['g:stem-boot','g:yo-irregular'],src:['gr-infinitivo-usos-a1','gr-subordinadas-sustantivas-a1','fn-habilidad-b1'],contrasts:['x:saber-poder'],note:'saber + inf = know how to; poder = be able / be allowed.'},
// u09 My routine
{id:'g:reflexive-routine',u:9,t:'Your daily routine: me levanto, te duchas, se acuesta',es:'Me levanto a las cinco. Vale se acuesta tarde. ¿A qué hora te despiertas?',en:'I get up at five. Vale goes to bed late. What time do you wake up?',pb:'A1',pcic:['gramatica:7.1.4'],req:['g:stem-boot','g:present-er-ir'],src:['gr-pronombre-se-a1','task-rutina'],note:'Unpacks c:me-llamo. Pronoun before the conjugated verb; attached to the infinitive (voy a levantarme).'},
{id:'g:estar-gerund',u:9,t:'What\'s happening right now: estoy trabajando',es:'Estoy trabajando, te llamo luego. ¿Qué estás haciendo?',en:'I\'m working, I\'ll call you later. What are you doing?',pb:'A1',pcic:['gramatica:9.4.2','gramatica:12.1'],req:['g:estar-location-states','g:present-er-ir'],src:['gr-gerundio-a2','gr-presente-indicativo-valores-a1'],contrasts:['x:present-progressive'],note:'Use only for right-now/temporary; plain present for habits and many "now" uses.'},
{id:'g:tener-que-hay-que',u:9,t:'What you have to do: tengo que, hay que, necesito',es:'Tengo que abrir a las seis. Hay que limpiar la máquina. No tienes que pagar.',en:'I have to open at six. The machine needs cleaning. You don\'t have to pay.',pb:'A1',pcic:['gramatica:12.1','nociones_generales'],req:['g:yo-irregular'],src:['gr-tener-que-hay-que-a1','nt-necesidad-obligacion-a2','fn-obligacion-necesidad-b1'],note:'Unpacks c:tengo-que and c:hay-que. no tener que = don\'t have to (not "must not").'},
// u10 Food and ordering
{id:'g:gustar-full',u:10,t:'Likes for everyone: le gusta, nos encanta, les interesa — and a mí también',es:'A Vale le encantan los buñuelos. A mí no me gusta el picante. —A mí tampoco.',en:'Vale loves buñuelos. I don\'t like spicy food. —Me neither.',pb:'A1',pcic:['gramatica:7.1.3','gramatica:7.1.6'],req:['g:gustar-basic'],src:['gr-verbos-predicativos-tipos-a2','gr-pronombres-me-te-nos-a1','fn-preferencia-comparativa-a2','task-gustos'],note:'encantar, interesar, importar, doler (me duele la cabeza). Reading practice so learners don\'t read le as the subject.'},
{id:'g:stem-e-i',u:10,t:'More inside-changers: pido, sirvo, sigo, repito',es:'Siempre pido lo mismo. ¿Me repites? Aquí sirven el mejor ajiaco.',en:'I always order the same thing. Can you repeat that? They serve the best ajiaco here.',pb:'A1',pcic:['gramatica:9.1.1'],req:['g:stem-boot'],src:['gr-presente-irregular-a2'],contrasts:['x:pedir-preguntar']},
{id:'g:direct-objects',u:10,t:'Not repeating the noun: lo, la, los, las (and the personal a)',es:'—¿El jugo? —Lo quiero sin azúcar. ¿Conoces a Vale? La conocí ayer.',en:'—The juice? —I want it without sugar. Do you know Vale? I met her yesterday.',pb:'A2',pcic:['gramatica:7.1.2','gramatica:12.2.2'],req:['g:gustar-full','g:preterite-er-ir'],src:['gr-objeto-directo-a1','gr-pronombres-atonos-a2','task-a2-pronombres'],note:'lo/la standard (no leísmo). Comprehension first: "who did what to whom?" (Lo ve María).'},
// u11 How life used to be
{id:'g:imperfect-habitual',u:11,t:'What used to happen: the full "used to" past (trabajaba, comía, vivía)',es:'De niño iba al café todos los domingos. Mi abuela cocinaba y yo comía.',en:'As a kid I used to go to the café every Sunday. My grandmother cooked and I ate.',pb:'A2',pcic:['gramatica:9.1.2'],req:['g:imperfect-states'],src:['imperfecto','gr-preterito-imperfecto-a2','task-a2-antes'],note:'Only three irregulars: ser, ir, ver.'},
{id:'g:preterite-spelling-stem',u:11,t:'Past-tense surprises: busqué, llegué, empecé, leyó, pidió, durmió',es:'Llegué tarde. Busqué las llaves. Vale pidió un aumento. Don Hernando se durmió.',en:'I arrived late. I looked for the keys. Vale asked for a raise. Don Hernando fell asleep.',pb:'A2',pcic:['gramatica:9.1.3','ortografia'],req:['g:preterite-irregular-strong','g:stem-e-i'],src:['gr-indefinido-irregular-a2','preterito']},
{id:'g:comparatives',u:11,t:'Comparing: más… que, menos… que, tan… como, mejor, peor',es:'Bogotá es más fría que Medellín. Este café es mejor que el otro. No es tan caro como dicen.',en:'Bogotá is colder than Medellín. This coffee is better than the other one. It\'s not as expensive as they say.',pb:'A2',pcic:['gramatica:2.5'],req:['g:adjective-agreement'],src:['gr-comparativos-a2','gr-comparativo-a2','task-a2-comparar'],note:'mayor/menor for age. más de + number.'},
// u12 Telling a story (checkpoint)
{id:'g:pret-vs-imperfect',u:12,t:'Two pasts in one story: what happened vs what things were like',es:'Era tarde y llovía. De repente alguien tocó la puerta.',en:'It was late and it was raining. Suddenly someone knocked on the door.',pb:'A2',pcic:['gramatica:9.1.2','gramatica:9.1.3'],req:['g:imperfect-habitual','g:preterite-irregular-strong'],src:['preterite-imperfect','gn-narrar-anecdota-a2','task-a2-anecdota'],contrasts:['x:pret-imp'],note:'Blocked here, then interleaved across sessions; one of the big five, recycled to C1.'},
{id:'g:imperfect-progressive',u:12,t:'Was doing it when…: estaba cocinando cuando sonó el teléfono',es:'Estaba cerrando el café cuando llegó el señor Altamira.',en:'I was closing the café when Mr Altamira arrived.',pb:'A2',pcic:['gramatica:9.4.2','gramatica:15.3.1'],req:['g:pret-vs-imperfect','g:estar-gerund'],src:['gr-gerundio-a2','preterite-imperfect']},
{id:'g:that-clauses',u:12,t:'Saying what you think, know and heard: creo que, sé que, dice que',es:'Creo que tienes razón. Dice que viene mañana. Sabía que ibas a decir eso.',en:'I think you\'re right. She says she\'s coming tomorrow. I knew you were going to say that.',pb:'A1',pcic:['gramatica:15.1.2'],req:['g:verb-infinitive'],src:['gr-subordinadas-sustantivas-a1','gr-creo-que-dice-que-a1','gr-objeto-directo-a1'],note:'que is never dropped (unlike English "I think you\'re right"). Unpacks c:creo-que.'},
// u13 Around the city
{id:'g:commands-tu',u:13,t:'Telling a friend what to do: ven, mira, espera, dime',es:'Mira esto. Ven conmigo. Sigue derecho y voltea a la izquierda.',en:'Look at this. Come with me. Go straight on and turn left.',pb:'A2',pcic:['gramatica:9.3'],req:['g:present-er-ir','g:yo-irregular'],src:['gr-imperativo-forma-a2','imperativo','gn-instrucciones-a2','task-direcciones'],note:'Regular = él form; 8 irregulars (ven, ten, pon, sal, haz, di, ve, sé).'},
{id:'g:commands-usted',u:13,t:'Telling a stranger (or a group) what to do: siga, voltee, vengan',es:'Siga derecho dos cuadras. Tome la TransMilenio. Pasen, sigan.',en:'Go straight two blocks. Take the TransMilenio. Come in, come in.',pb:'A2',pcic:['gramatica:9.3'],req:['g:commands-tu'],src:['gr-imperativo-forma-a2','imperativo','nt-orientacion-direccion-a1','nt-movimiento-estabilidad-a2'],contrasts:['x:tu-usted'],note:'Colombia uses usted widely; ustedes is the only plural. Taught as "the opposite vowel" before the subjunctive exists.'},
{id:'g:indirect-objects',u:13,t:'To whom, for whom: le, les (le pregunto, les explico)',es:'Le pregunté al señor dónde estaba la estación. ¿Les explico el camino?',en:'I asked the man where the station was. Shall I explain the way to you?',pb:'A2',pcic:['gramatica:7.1.3','gramatica:12.2.3'],req:['g:gustar-full','g:direct-objects'],src:['gr-objeto-indirecto-a2','gr-pronombres-atonos-a2'],contrasts:['x:lo-le'],note:'Doubling with a + name is normal (le dije a Vale).'},
// u14 Joining it up
{id:'g:relative-que',u:14,t:'Adding detail with que: el señor que vende arepas',es:'El señor que vende arepas es mi vecino. La receta que encontré es de 1975.',en:'The man who sells arepas is my neighbour. The recipe I found is from 1975.',pb:'A1',pcic:['gramatica:7.2','gramatica:15.2'],req:['g:that-clauses'],src:['gr-relativo-que-a1','gr-subordinadas-adjetivas-a1'],note:'que for people and things; never dropped.'},
{id:'g:cause-result',u:14,t:'Why and so: porque, como, por eso, así que',es:'Como llovía, no salimos. No tengo plata, por eso no voy. Estoy cansado, así que me voy.',en:'As it was raining, we didn\'t go out. I have no money, that\'s why I\'m not going. I\'m tired, so I\'m leaving.',pb:'A2',pcic:['gramatica:15.3.4','gramatica:15.3.7'],req:['g:that-clauses'],src:['gr-causales-a2','dc-conectores-a1','task-contar'],note:'como (cause) goes first; porque goes second.'},
{id:'g:prep-pronouns',u:14,t:'After for, with, to: para mí, contigo, sin ti',es:'¿Esto es para mí? ¿Vienes conmigo? Sin ti no puedo.',en:'Is this for me? Are you coming with me? I can\'t without you.',pb:'A2',pcic:['gramatica:7.1.6'],req:['g:gustar-full'],src:['gr-pronombres-tonicos-a2']},
// ---------------- A2 ----------------
// u15 How are you feeling?
{id:'g:ser-estar-adjectives',u:15,t:'"Is" for what it\'s like vs "is" for how it is right now: es aburrido / está aburrido',es:'Don Hernando es muy tranquilo, pero hoy está nervioso. La sopa está rica.',en:'Don Hernando is very calm, but today he\'s nervous. The soup is delicious.',pb:'A2',pcic:['gramatica:12.2.1'],req:['g:estar-location-states','g:adjective-agreement'],src:['gr-ser-estar-adjetivos-a2','ser-estar'],contrasts:['x:ser-estar-adj'],note:'Big five. Weight reading toward estar. Meaning-changers: aburrido, listo, rico, malo, vivo.'},
{id:'g:estar-participle',u:15,t:'The state something is in: está cerrado, está roto, estoy preocupado',es:'La máquina está dañada. La puerta estaba abierta. Estamos muy preocupados.',en:'The machine is broken. The door was open. We\'re very worried.',pb:'A2',pcic:['gramatica:9.4.3','gramatica:12.1'],req:['g:ser-estar-adjectives','g:perfecto-experience'],src:['gr-participio-adjetival-a1','nt-acabado-b1'],note:'Participle agrees like an adjective.'},
{id:'g:parecer-quedar',u:15,t:'More "backwards" verbs: me parece, me queda, me cae bien, me hace falta',es:'Me parece una buena idea. Esa chaqueta te queda grande. Tu amigo me cae muy bien.',en:'It seems like a good idea to me. That jacket is too big for you. I really like your friend.',pb:'A2',pcic:['gramatica:12.1','gramatica:7.1.3'],req:['g:gustar-full'],src:['gr-verbos-predicativos-tipos-a2','fn-valorar-a1']},
// u16 Shopping (checkpoint)
{id:'g:object-pronoun-position',u:16,t:'Where the little words go: lo voy a comprar = voy a comprarlo',es:'Lo voy a pensar. = Voy a pensarlo. ¿Me estás escuchando?',en:'I\'m going to think about it. Are you listening to me?',pb:'A2',pcic:['gramatica:7.1.2','gramatica:7.1.3'],req:['g:direct-objects','g:indirect-objects','g:ir-a-plans'],src:['gr-pronombres-posicion-a2','gr-pronombres-atonos-a2'],note:'Before the conjugated verb or glued to the infinitive/gerund; both correct.'},
{id:'g:superlatives',u:16,t:'The best, the cheapest, super-cheap: el más barato, carísimo',es:'Es el café más viejo del barrio. Esos zapatos están carísimos.',en:'It\'s the oldest café in the neighbourhood. Those shoes are really expensive.',pb:'A2',pcic:['gramatica:2.5'],req:['g:comparatives'],src:['gr-comparativos-a2','gr-modificadores-adverbios-b1','fn-valorar-a2'],note:'de, not "in", after a superlative. -ísimo spelling (riquísimo, larguísimo).'},
{id:'g:double-pronouns',u:16,t:'Two little words together: me lo, te la, se lo',es:'—¿Me empaca la camisa? —Claro, ya se la empaco. ¿Me lo prestas?',en:'—Can you wrap the shirt for me? —Of course, I\'ll wrap it for you. Will you lend it to me?',pb:'B1',pcic:['gramatica:7.1.5'],req:['g:object-pronoun-position'],src:['gr-pronombres-combinados-b1','gr-pronombres-atonos-a2'],note:'le/les → se before lo/la. Comprehension first; production lags.'},
// u17 Making plans
{id:'g:si-present',u:17,t:'If… then: si quieres, vamos; si llueve, me quedo',es:'Si quieres, vamos al cine. Si llueve, nos quedamos en casa. Si ves a Vale, dile que la llamo.',en:'If you want, we\'ll go to the cinema. If it rains, we\'ll stay home. If you see Vale, tell her I\'ll call her.',pb:'A2',pcic:['gramatica:15.3.6'],req:['g:ir-a-plans','g:commands-tu'],src:['gr-condicionales-a2','gr-condicionales-b1']},
{id:'g:prep-infinitive',u:17,t:'Before leaving, after eating, on arriving: antes de, después de, al + verb',es:'Antes de salir, cierra la puerta. Después de comer, tomamos tinto. Al llegar, me llamas.',en:'Before leaving, close the door. After eating, we have coffee. When you arrive, call me.',pb:'A2',pcic:['gramatica:9.4.1','gramatica:15.3.1'],req:['g:verb-infinitive'],src:['gr-infinitivo-usos-a1','nt-duracion-transcurso-a1'],note:'Spanish uses the infinitive where English uses -ing.'},
{id:'g:cuando-indicative',u:17,t:'When, while, every time: cuando, mientras, siempre que + present or past',es:'Cuando llego, Vale ya está aquí. Mientras yo cocinaba, él lavaba. Cuando era niño, vivía en Toronto.',en:'When I arrive, Vale is already here. While I was cooking, he was washing up. When I was a kid I lived in Toronto.',pb:'A2',pcic:['gramatica:15.3.1'],req:['g:pret-vs-imperfect'],src:['gr-temporales-b1','dc-deixis-temporal-a2'],note:'Only habitual/past cuando here; cuando + future meaning waits for the subjunctive (g:subj-cuando-future).'},
// u18 On the road
{id:'g:por-para-1',u:18,t:'For and by, part 1: para (destination, purpose, deadline) vs por (through, because of, per)',es:'Salimos para Medellín por la mañana. Gracias por todo. Es para el viernes.',en:'We leave for Medellín in the morning. Thanks for everything. It\'s for Friday.',pb:'A2',pcic:['gramatica:12.2.4'],req:['g:prep-infinitive'],src:['por-para','gr-oraciones-finales-a1'],contrasts:['x:por-para'],note:'Rules of thumb only; second pass at B1, third at B2.'},
{id:'g:commands-with-pronouns',u:18,t:'Commands with the little words: dímelo, siéntese, tráiganmelo',es:'Siéntese, por favor. Dímelo. Bájese en la próxima. Tráiganmelo mañana.',en:'Sit down, please. Tell me. Get off at the next one. Bring it to me tomorrow.',pb:'A2',pcic:['gramatica:9.3','gramatica:7.1.5'],req:['g:commands-usted','g:double-pronouns'],src:['gr-pronombres-posicion-a2','imperativo'],note:'Glued on in positive commands, with an accent to keep the stress.'},
{id:'g:possessives-stressed',u:18,t:'Mine, yours, his: mío, tuyo, suyo (un amigo mío)',es:'—¿Esta maleta es suya? —No, la mía es la roja. Un amigo mío vive en Santa Marta.',en:'—Is this suitcase yours? —No, mine is the red one. A friend of mine lives in Santa Marta.',pb:'A2',pcic:['gramatica:5'],req:['g:possessives'],src:['gr-posesivos-tonicos-a2']},
// u19 Work and studies
{id:'g:se-impersonal',u:19,t:'People in general: se habla, se vende, se necesita, se puede',es:'Se necesita mesero. Aquí se habla inglés. ¿Se puede pagar con tarjeta?',en:'Waiter needed. English spoken here. Can you pay by card?',pb:'B1',pcic:['gramatica:7.1.4'],req:['g:reflexive-routine'],src:['gr-se-multiuso-b1','gr-oraciones-simples-a2'],note:'Plural agreement with plural things (se venden arepas).'},
{id:'g:relatives-donde-lo-que',u:19,t:'Where, who and the thing that: donde, quien, lo que',es:'Es el lugar donde trabajé. Lo que necesito es tiempo. Es la persona con quien hablé.',en:'It\'s the place where I worked. What I need is time. She\'s the person I spoke with.',pb:'A2',pcic:['gramatica:7.2','gramatica:15.2'],req:['g:relative-que'],src:['gr-relativas-b1','gr-adverbios-relativos-b1','fn-identificar-b1'],note:'lo que = "what" in statements (not qué).'},
{id:'g:article-uses',u:19,t:'When Spanish says "the" and English doesn\'t (and the reverse)',es:'Me gusta el café. Soy ingeniero. Los lunes trabajo. Juego al fútbol. Es la una.',en:'I like coffee. I\'m an engineer. On Mondays I work. I play football. It\'s one o\'clock.',pb:'A2',pcic:['gramatica:3.1','gramatica:3.3'],req:['g:gender-articles'],src:['gr-articulo-definido-a1','gr-articulo-definido-distribucion-a2','gr-articulo-definido-valores-a2','gr-nombres-escuetos-a2','gr-articulo-indefinido-valores-a2'],note:'General statements take the article; no article with professions after ser; el agua.'},
// u20 Guesses and predictions (checkpoint)
{id:'g:future-conjecture',u:20,t:'Guessing out loud: ¿Dónde estará? Serán las tres. Tendrá unos sesenta años.',es:'¿Dónde estará Simón? Estará con Don Hernando. Serán las once.',en:'Where can Simón be? He\'s probably with Don Hernando. It must be about eleven.',pb:'B1',pcic:['gramatica:9.1.4'],req:['g:ir-a-plans','g:yo-irregular'],src:['futuro','gr-futuro-imperfecto-b1','gr-modalidad-b1'],note:'In LatAm speech the -ré future is mostly for guesses. Forms are taught here through the guess use: one set of endings on the whole infinitive, twelve short stems (tendr-, pondr-, sabr-, habr-…).'},
{id:'g:future-promises',u:20,t:'Promises, predictions and formal plans: te llamaré, lloverá, será difícil',es:'Te prometo que volveré. Mañana lloverá en Bogotá. No será fácil.',en:'I promise I\'ll come back. Tomorrow it will rain in Bogotá. It won\'t be easy.',pb:'B1',pcic:['gramatica:9.1.4'],req:['g:future-conjecture'],src:['futuro','fn-expresar-planes-b1','task-b1-planes'],contrasts:['x:ir-a-future'],note:'ir a stays the default for plans; -ré for promises, forecasts, written plans and the news.'},
{id:'g:conditional',u:20,t:'Would: me encantaría, podrías, deberías — and yo que tú…',es:'Me encantaría ir. ¿Podrías ayudarme? Deberías descansar. Yo que tú, no firmaría.',en:'I\'d love to go. Could you help me? You should rest. If I were you, I wouldn\'t sign.',pb:'B1',pcic:['gramatica:9.1.5'],req:['g:future-conjecture'],src:['condicional','gr-condicional-simple-b1','fn-cortesia-condicional-a1','fn-aconsejar-a2'],note:'Same stems as the future. Unpacks c:me-gustaria and c:podria.'},
// u21 What I want you to do
{id:'g:subj-wanting',u:21,t:'Wanting someone else to do something: quiero que vengas',es:'Quiero que trabajes conmigo. Necesito que me ayudes. Prefiero que lo hablemos.',en:'I want you to work with me. I need you to help me. I\'d rather we talk about it.',pb:'B1',pcic:['gramatica:9.2.1','gramatica:15.1.2'],req:['g:that-clauses','g:commands-usted','g:verb-infinitive'],src:['gr-presente-subjuntivo-b1','presubj','gr-subordinadas-sustantivas-b1','fn-expresar-deseos-b1','task-b1-deseos'],contrasts:['x:inf-vs-que-subj'],note:'The subjunctive enters with ONE trigger (wanting) and the "opposite vowel" forms they already know from usted commands. Different subject → que + subjunctive; same subject → infinitive.'},
{id:'g:subj-irregulars',u:21,t:'The irregular "wish" forms: sea, vaya, tenga, haga, sepa, esté, haya',es:'Quiero que seas sincero. Necesito que vayas al banco. Espero que haya tiempo.',en:'I want you to be honest. I need you to go to the bank. I hope there\'s time.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-wanting'],src:['gr-presente-subjuntivo-b1','presubj','gr-formulas-subjuntivo-a2'],note:'Built on the yo form (tengo → tenga) plus six true irregulars.'},
{id:'g:negative-commands',u:21,t:'Telling someone not to: no toques, no se preocupe, no lo hagan',es:'No toques eso. No se preocupe. No me digas. No lo firmen todavía.',en:'Don\'t touch that. Don\'t worry. You don\'t say. Don\'t sign it yet.',pb:'B1',pcic:['gramatica:9.3'],req:['g:subj-irregulars','g:commands-with-pronouns'],src:['impneg','gr-imperativo-valores-b1'],note:'Pronouns go BEFORE the verb in negative commands.'},
// u22 Good news, bad news
{id:'g:subj-wishes',u:22,t:'Wishing: ojalá, espero que, que te vaya bien',es:'Ojalá no llueva. Espero que te guste. ¡Que te mejores! ¡Que les vaya bien!',en:'I hope it doesn\'t rain. I hope you like it. Get well soon! Good luck, all of you!',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-irregulars'],src:['gr-formulas-subjuntivo-a2','fn-espero-esperanza-b1','fn-buenos-deseos-a2','fn-buenos-deseos-b1'],note:'Unpacks c:ojala and c:que-te-mejores.'},
{id:'g:exclamations',u:22,t:'Reacting: ¡Qué bueno!, ¡Qué pena!, ¡Qué tan lindo!, ¡Cuánta gente!',es:'¡Qué bueno verte! ¡Qué casa tan bonita! ¡Cuánto tiempo!',en:'How good to see you! What a lovely house! Long time no see!',pb:'A2',pcic:['gramatica:7.4'],req:['g:adjective-agreement'],src:['gr-interrogativos-exclamativos-a2','fn-valorar-a2','fn-felicitar-a2','task-a2-animo'],note:'¡Qué + noun + tan/más + adj! Accent marks on exclamative qué/cuánto.'},
{id:'g:diminutives',u:22,t:'Making it small and friendly: un tintico, ahorita, un momentico',es:'¿Me regala un tintico? Espérame un momentico. Ahorita voy.',en:'Could I have a little coffee? Wait a moment. I\'m coming (in a bit).',pb:'A2',pcic:['gramatica:1.1.2','morfologia'],req:['g:gender-articles'],src:['gr-sustantivos-especiales-a2'],placementNote:'teaching_choice',note:'Colombia: -ico after t (momentico, ratico, gatico); -ito elsewhere. Warmth and politeness, not only size. ahorita = soon/now depending on region.'},
// u23 Sorting things out (services)
{id:'g:que-vs-cual',u:23,t:'What or which: ¿qué? vs ¿cuál?',es:'¿Cuál es tu número de celular? ¿Qué quieres tomar? ¿Cuál prefieres?',en:'What\'s your phone number? What would you like to drink? Which one do you prefer?',pb:'A2',pcic:['gramatica:7.3'],req:['g:questions'],src:['gr-interrogativos-exclamativos-a2','dc-interrogativos-neutros-a2','gr-interrogativos-b1']},
{id:'g:indefinites',u:23,t:'Some, any, none: algún, alguien, algo — ningún, nadie, nada',es:'¿Hay algún problema? No tengo ninguna queja. ¿Alguien sabe algo?',en:'Is there any problem? I don\'t have any complaints. Does anyone know anything?',pb:'B1',pcic:['gramatica:6.1','gramatica:7'],req:['g:negation-words'],src:['gr-indefinidos-negativos-b1','gr-cuantificadores-b1'],note:'alguno/ninguno shorten before a masculine noun.'},
{id:'g:hace-que-desde',u:23,t:'How long it\'s been going on: hace un año que…, desde hace…, llevo…',es:'Hace tres meses que vivo aquí. Trabajo aquí desde hace un año. Llevo una hora esperando.',en:'I\'ve lived here for three months. I\'ve worked here for a year. I\'ve been waiting for an hour.',pb:'A2',pcic:['nociones_generales','gramatica:9.1.1'],req:['g:hace-ago','g:estar-gerund'],src:['nt-referencias-generales-a2','nt-inicio-duracion-fin-a2','nt-localizacion-tiempo-a2'],note:'English present perfect → Spanish PRESENT here.'},
// u24 Reasons and choices (checkpoint)
{id:'g:pero-sino',u:24,t:'But and but rather: pero vs sino (no es caro, sino barato)',es:'No es colombiano, sino canadiense. No quiero té sino café. Es caro, pero vale la pena.',en:'He isn\'t Colombian but Canadian. I don\'t want tea, I want coffee. It\'s expensive, but it\'s worth it.',pb:'A2',pcic:['gramatica:14.3'],req:['g:negation-words'],src:['dc-conectores-a1','gr-oraciones-simples-a2'],note:'sino que before a verb.'},
{id:'g:aunque-indicative',u:24,t:'Even though: aunque + a fact',es:'Aunque es tarde, el café está lleno. Aunque no me gusta, lo hago.',en:'Even though it\'s late, the café is full. Even though I don\'t like it, I do it.',pb:'B1',pcic:['gramatica:15.3.9'],req:['g:cause-result'],src:['gr-concesivas-b1'],note:'aunque + subjunctive (hypothetical) waits until B2 (g:subj-concessive).'},
{id:'g:tanto-como',u:24,t:'As much as, as many as: tanto como, tanta gente, igual de',es:'Trabajo tanto como tú. No hay tantos clientes como antes. Es igual de caro.',en:'I work as much as you. There aren\'t as many customers as before. It\'s just as expensive.',pb:'A2',pcic:['gramatica:2.5','gramatica:15.3.8'],req:['g:comparatives'],src:['gr-comparativos-a2','gr-comparativas-b1']},
// u25 Places and people in detail
{id:'g:le-doubling',u:25,t:'Saying who twice: le di el libro a Vale',es:'Le di la llave a Vale. ¿Le dijiste a tu mamá? A mí me parece bien.',en:'I gave the key to Vale. Did you tell your mom? I think it\'s fine.',pb:'A2',pcic:['gramatica:7.1.3'],req:['g:indirect-objects'],src:['gr-objeto-indirecto-a2','dc-tematizacion-a2']},
{id:'g:adverbs-mente',u:25,t:'How you do it: -mente (rápidamente, realmente) and other ways to say how',es:'Habla lentamente. Realmente no sé. Lo hizo rápido y bien.',en:'She speaks slowly. I really don\'t know. He did it quickly and well.',pb:'A2',pcic:['gramatica:8.1'],req:['g:adjective-agreement'],src:['gr-adverbios-modo-cantidad-b1','gr-adverbios-circunstanciales-a2','gr-adverbios-lugar-tiempo-cantidad-a1'],note:'Feminine form + -mente; keeps the accent. In speech LatAm often uses the adjective (habla rápido).'},
{id:'g:reported-past-basic',u:25,t:'Telling what someone said: me dijo que estaba cansado, me preguntó si…',es:'Me dijo que estaba cansado. Le pregunté si quería venir. Me contó que se iba a Cali.',en:'He told me he was tired. I asked her if she wanted to come. She told me she was going to Cali.',pb:'B1',pcic:['tacticas_pragmaticas:1.5.2','gramatica:15.1.2'],req:['g:that-clauses','g:pret-vs-imperfect'],src:['nt-expresion-verbal-a2','fn-dar-informacion-a2'],note:'Only the easy shifts: present → imperfect, ir a → iba a. Backshift with había/vendría at B1.'},
// u26 Telling it well
{id:'g:gerund-ways',u:26,t:'By doing, while doing: aprendí leyendo, sigue lloviendo, va mejorando',es:'Aprendí español viendo novelas. Sigue lloviendo. El café va mejorando.',en:'I learned Spanish by watching soaps. It\'s still raining. The café is getting better.',pb:'A2',pcic:['gramatica:9.4.2'],req:['g:estar-gerund'],src:['gr-gerundio-a2','gr-perifrasis-verbales-b1','nt-ciclo-accion-b1'],note:'Gerund = by/while -ing; never as a noun (Nadar es bueno, not *Nadando es bueno).'},
{id:'g:time-sequence',u:26,t:'Keeping a story in order: primero, luego, al final, ese día, al día siguiente',es:'Ese día llegué tarde. Al día siguiente, todo cambió. Dos semanas después…',en:'That day I arrived late. The next day, everything changed. Two weeks later…',pb:'A2',pcic:['nociones_generales','tacticas_pragmaticas'],req:['g:pret-vs-imperfect'],src:['dc-deixis-temporal-a2','dc-estructuradores-a2','gn-narrar-anecdota-a2','nt-tiempo-referencias-futuro-pasado-presente-b1'],note:'Shifts deixis (hoy → ese día, mañana → al día siguiente); needed for reported speech.'},
{id:'g:acabar-de-ya-todavia',u:26,t:'Just, already, still, not yet: acabo de, ya, todavía, ya no',es:'Acabo de llegar. ¿Ya comiste? Todavía no. Ya no trabajo allá.',en:'I\'ve just arrived. Have you eaten yet? Not yet. I don\'t work there any more.',pb:'A2',pcic:['nociones_generales'],req:['g:perfecto-experience','g:preterite-er-ir'],src:['nt-anterioridad-a2','nt-inicio-duracion-fin-a2'],note:'LatAm: ¿Ya comiste? (preterite) is the everyday form; unpacks c:ya-comiste.'},
// u27 Writing it down
{id:'g:written-register-a2',u:27,t:'Messages, emails and reviews: openings, closings and usted in writing',es:'Estimada señora Ruiz: Le escribo para… Quedo atenta a su respuesta. Un abrazo,',en:'Dear Mrs Ruiz: I am writing to… I look forward to your reply. Hugs,',pb:'A2',pcic:['generos_discursivos','gramatica:7.1.1'],req:['g:indirect-objects','g:conditional'],src:['gn-generos-escritos-a2','fn-saludar-escrito-a2','gn-generos-escritos-a1','task-a2-escribir'],note:'Punctuation of letters (colon after the greeting), usted forms in formal mail.'},
{id:'g:para-que',u:27,t:'So that: para + verb vs para que + someone else',es:'Te escribo para pedirte un favor. Te escribo para que me ayudes.',en:'I\'m writing to ask you a favour. I\'m writing so that you\'ll help me.',pb:'B1',pcic:['gramatica:15.3.5'],req:['g:subj-irregulars','g:por-para-1'],src:['gr-oraciones-finales-a1','gr-sub-adv-finales-c1'],contrasts:['x:para-inf-que'],note:'Same rule as quiero / quiero que.'},
{id:'g:subj-emotion-intro',u:27,t:'Reacting to what others do: me alegra que, me molesta que, qué bueno que',es:'Me alegra que estés aquí. Qué bueno que viniste… / que vinieras. Me molesta que llegue tarde.',en:'I\'m glad you\'re here. How good that you came. It bothers me that he arrives late.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-wishes','g:parecer-quedar'],src:['fn-me-alegro-b1','fn-contento-encantado-b1','gr-ser-impersonal-b1'],note:'Same "backwards" verbs as gustar, now with que + subjunctive. Present-reference only.'},
// ---------------- B1 ----------------
// u28 What I think
{id:'g:subj-opinion-negated',u:28,t:'I think so / I don\'t think so: creo que es… vs no creo que sea…',es:'Creo que tienes razón. No creo que tengas razón. Me parece que sí. No me parece que sea justo.',en:'I think you\'re right. I don\'t think you\'re right. I think so. I don\'t think it\'s fair.',pb:'B1',pcic:['gramatica:9.2.1','gramatica:15.1.2'],req:['g:subj-irregulars','g:that-clauses'],src:['gr-subordinadas-sustantivas-b1','fn-dar-opinion-b1','task-b1-opinion'],contrasts:['x:creo-no-creo'],note:'Big five. Statement = indicative; denial = subjunctive.'},
{id:'g:subj-value',u:28,t:'Judging: es importante que, es mejor que, es normal que, es una pena que',es:'Es importante que lo leas. Es mejor que esperemos. Es una pena que cierren.',en:'It\'s important that you read it. It\'s better for us to wait. It\'s a shame they\'re closing.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-opinion-negated'],src:['gr-ser-impersonal-b1','fn-valorar-b1','nt-evaluacion-valor-b1','nt-exito-utilidad-importancia-b1'],note:'Es verdad/cierto/obvio que + indicative (a fact) vs value + subjunctive.'},
{id:'g:lo-adjective',u:28,t:'The good thing, the worst part: lo bueno, lo malo, lo mejor es que',es:'Lo bueno es que tenemos clientes. Lo peor fue la espera. Lo importante es seguir.',en:'The good thing is we have customers. The worst part was the wait. What matters is to keep going.',pb:'B1',pcic:['gramatica:3.1'],req:['g:relatives-donde-lo-que'],src:['gr-articulo-definido-valores-b2','dc-intensificacion-discurso-b1']},
// u29 Agreeing and arguing
{id:'g:subj-doubt',u:29,t:'Doubt and possibility: dudo que, es posible que, puede que',es:'Dudo que Altamira cambie de idea. Es posible que llueva. Puede que tengas razón.',en:'I doubt Altamira will change his mind. It might rain. You may be right.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-opinion-negated'],src:['fn-posibilidad-b1','fn-mostrar-escepticismo-b1','fn-certeza-evidencia-b1'],note:'subjunctive refers to present or future here.'},
{id:'g:quizas-a-lo-mejor',u:29,t:'Maybe: quizás, tal vez + either mood; a lo mejor + fact form',es:'Quizás venga mañana. A lo mejor está enfermo. Tal vez tienes razón.',en:'Maybe he\'ll come tomorrow. Maybe he\'s sick. Maybe you\'re right.',pb:'B1',pcic:['gramatica:9.2.1','gramatica:8.4'],req:['g:subj-doubt'],src:['gr-modalidad-b1','fn-posibilidad-b1'],note:'a lo mejor always indicative; quizás/tal vez: subjunctive = less sure.'},
{id:'g:conditional-past-guess',u:29,t:'Guessing about the past: serían las diez, tendría veinte años',es:'Serían las diez cuando llegó. Tendría unos veinte años. ¿Por qué lo haría?',en:'It must have been about ten when he arrived. She\'d have been about twenty. Why would he have done it?',pb:'B1',pcic:['gramatica:9.1.5'],req:['g:future-conjecture','g:conditional'],src:['condicional','gr-condicional-simple-b1']},
// u30 Feelings
{id:'g:subj-emotion',u:30,t:'Feelings about what others do, fully: me da miedo que, me sorprende que, siento que',es:'Me da miedo que vendan el edificio. Me sorprende que no lo sepas. Siento que te sientas así.',en:'I\'m scared they\'ll sell the building. I\'m surprised you don\'t know. I\'m sorry you feel that way.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-emotion-intro'],src:['fn-me-alegro-b1','fn-miedo-ansiedad-preocupacion-b1','fn-enfado-indignacion-b1','fn-empatia-b1','fn-sorpresa-extraneza-b1'],note:'Same subject → infinitive (me alegra verte).'},
{id:'g:verbs-of-change',u:30,t:'Becoming: ponerse nervioso, quedarse callado, volverse famoso, hacerse rico',es:'Me puse rojo. Se quedó callado. Se volvió muy serio. Quiere hacerse médico.',en:'I went red. He went quiet. He became very serious. She wants to become a doctor.',pb:'B2',pcic:['gramatica:12.1'],req:['g:reflexive-routine','g:ser-estar-adjectives'],src:['gr-nucleo-verbal-copulativos-b2','nt-cambio-c1','nt-cambio-a2'],note:'ponerse = sudden mood/colour; quedarse = result; volverse = character; hacerse = effort/career.'},
{id:'g:se-meaning-change',u:30,t:'When "se" changes the meaning: ir/irse, dormir/dormirse, quedar/quedarse',es:'Me voy. Me dormí en la reunión. Nos quedamos en casa. Quedamos a las seis.',en:'I\'m off. I fell asleep in the meeting. We stayed at home. We agreed to meet at six.',pb:'B1',pcic:['gramatica:7.1.4'],req:['g:reflexive-routine'],src:['gr-se-multiuso-b1','nt-movimiento-estabilidad-a2'],contrasts:['x:ir-irse']},
// u31 A longer story
{id:'g:pluperfect',u:31,t:'Had already happened: había llegado, ya se habían ido',es:'Cuando llegué, Vale ya se había ido. Nunca había visto tanta gente.',en:'When I arrived, Vale had already left. I had never seen so many people.',pb:'B1',pcic:['gramatica:9.1.8'],req:['g:pret-vs-imperfect','g:perfecto-experience'],src:['gr-pluscuamperfecto-b1','plusc','task-b1-relato']},
{id:'g:narrative-pasts',u:31,t:'Telling a story with all your pasts: what happened, what it was like, what had happened before',es:'Era domingo. Tomás abrió la caja que había encontrado y vio una carta.',en:'It was Sunday. Tomás opened the box he had found and saw a letter.',pb:'B1',pcic:['gramatica:9.1.2','gramatica:9.1.3','gramatica:9.1.8'],req:['g:pluperfect'],src:['gr-pasados-repaso-b1','gn-narrar-estructura-b1','fn-introducir-tema-relato-b1','fn-concluir-relato-b1'],note:'Foreground/background; the LatAm perfecto only for open-ended experience.'},
{id:'g:reported-backshift',u:31,t:'Reporting further back: dijo que había llamado, que vendría',es:'Dijo que había llamado tres veces. Prometió que vendría. Me explicó que no lo sabía.',en:'She said she had called three times. He promised he would come. He explained that he didn\'t know.',pb:'B1',pcic:['tacticas_pragmaticas:1.5.2'],req:['g:reported-past-basic','g:pluperfect','g:conditional'],src:['nt-expresion-verbal-a2','nt-reflexion-expresion-b1','dc-cita-b2']},
// u32 Advice and plans (checkpoint)
{id:'g:subj-influence',u:32,t:'Advising and asking: te recomiendo que, te pido que, le aconsejo que',es:'Te recomiendo que hables con un abogado. Le pido que me escuche. No dejes que te asuste.',en:'I recommend you talk to a lawyer. I\'m asking you to listen to me. Don\'t let him scare you.',pb:'B1',pcic:['gramatica:9.2.1'],req:['g:subj-wanting','g:indirect-objects'],src:['fn-aconsejar-b1','fn-proponer-sugerir-b1','task-b1-consejo'],note:'Indirect object + que + subjunctive.'},
{id:'g:subj-cuando-future',u:32,t:'When it happens (it hasn\'t yet): cuando llegues, en cuanto sepa, hasta que vuelva',es:'Cuando llegues, llámame. En cuanto sepa algo, te aviso. No me voy hasta que vuelva.',en:'When you arrive, call me. As soon as I know anything, I\'ll let you know. I\'m not leaving until he comes back.',pb:'B1',pcic:['gramatica:15.3.1'],req:['g:subj-irregulars','g:cuando-indicative'],src:['gr-temporales-b1'],contrasts:['x:cuando-ind-subj'],note:'antes de que always subjunctive.'},
{id:'g:subj-purpose-full',u:32,t:'Purpose and plans for others: para que, sin que, antes de que',es:'Lo dejo aquí para que lo veas. Salió sin que nadie lo viera… / sin que nadie lo note.',en:'I\'ll leave it here so you can see it. He left without anyone noticing.',pb:'B1',pcic:['gramatica:15.3.5'],req:['g:para-que','g:subj-cuando-future'],src:['gr-sub-adv-finales-c1','gr-oraciones-finales-a1'],note:'Present-tense frames only at this point.'},
// u33 Looking for something
{id:'g:subj-relative',u:33,t:'Looking for one that…: busco un local que tenga ventanas',es:'Buscamos un local que tenga cocina. ¿Conoces a alguien que sepa de leyes? No hay nada que podamos hacer.',en:'We\'re looking for a place that has a kitchen. Do you know anyone who knows about law? There\'s nothing we can do.',pb:'B1',pcic:['gramatica:15.2'],req:['g:relatives-donde-lo-que','g:subj-irregulars'],src:['gr-relativas-b1','gr-subordinadas-relativas-tipos-b2'],contrasts:['x:relative-ind-subj'],note:'Known thing = indicative; unknown/non-existent = subjunctive.'},
{id:'g:relatives-prepositions',u:33,t:'Relatives after a preposition: el local en el que, la gente con la que, a quien',es:'Es el edificio en el que nació mi abuela. La persona a quien le escribí no contestó.',en:'It\'s the building my grandmother was born in. The person I wrote to didn\'t answer.',pb:'B2',pcic:['gramatica:7.2','gramatica:15.2'],req:['g:relatives-donde-lo-que'],src:['gr-el-que-relativos-b2','gr-quien-quienes-b2','gr-relativo-donde-b2'],note:'Spanish never strands the preposition.'},
{id:'g:cada-cualquier',u:33,t:'Each, any at all: cada, cualquier, cualquiera, todo/toda',es:'Cada mesa tiene su historia. Cualquier persona puede venir. Me sirve cualquiera.',en:'Each table has its story. Anyone can come. Any one will do.',pb:'B1',pcic:['gramatica:6.1'],req:['g:quantifiers'],src:['gr-cuantificadores-b1','gr-cuantificadores-numerales-cualquier-b2']},
// u34 Mishaps
{id:'g:se-accidental',u:34,t:'It just happened to me: se me olvidó, se me cayó, se nos dañó',es:'Se me olvidaron las llaves. Se le cayó el celular. Se nos dañó la nevera.',en:'I forgot my keys. She dropped her phone. Our fridge broke down.',pb:'B2',pcic:['gramatica:7.1.4'],req:['g:indirect-objects','g:se-impersonal'],src:['gr-pronombre-personal-b2','gr-posesivo-dativo-b1'],note:'The thing is the subject; the person is the indirect object. Very common in Colombia.'},
{id:'g:possessive-dative',u:34,t:'Body parts and belongings without "my": me duele la espalda, le robaron el celular',es:'Me corté el dedo. Le robaron la billetera. Me lavo el pelo.',en:'I cut my finger. They stole his wallet. I wash my hair.',pb:'B1',pcic:['gramatica:7.1.3'],req:['g:se-accidental'],src:['gr-posesivo-dativo-b1','fn-sensaciones-fisicas-b1']},
{id:'g:subj-perfect',u:34,t:'Hoping or doubting it has happened: espero que hayas llegado bien',es:'Espero que no se haya perdido. No creo que lo hayan leído. Me alegra que hayas venido.',en:'I hope he hasn\'t got lost. I don\'t think they\'ve read it. I\'m glad you came.',pb:'B2',pcic:['gramatica:9.2.3'],req:['g:subj-doubt','g:perfecto-experience'],src:['perfsubj','gr-perfsubj-valores-b2'],note:'In LatAm this also covers the recent finished past under a trigger (Me alegra que hayas venido).'},
// u35 At the doctor
{id:'g:por-para-2',u:35,t:'For and by, part 2: por + time/means/exchange, para + opinion/comparison',es:'Lo tomas tres veces por día. Para mí, es grave. Para ser lunes, hay mucha gente. Lo cambié por otro.',en:'You take it three times a day. For me, it\'s serious. For a Monday, there are a lot of people. I swapped it for another.',pb:'B1',pcic:['gramatica:12.2.4'],req:['g:por-para-1'],src:['gr-por-para-b1','por-para'],contrasts:['x:por-para']},
{id:'g:impersonal-obligation',u:35,t:'General advice and rules: hay que, se debe, uno tiene que, conviene',es:'Hay que tomar mucha agua. No se debe fumar aquí. Uno nunca sabe.',en:'You need to drink lots of water. Smoking isn\'t allowed here. You never know.',pb:'B1',pcic:['gramatica:7.1.4','nociones_generales'],req:['g:se-impersonal','g:tener-que-hay-que'],src:['nt-necesidad-obligacion-b1','fn-falta-obligacion-b2','fn-obligacion-necesidad-c1']},
{id:'g:deber-modal',u:35,t:'Should, must, must be: debes, deberías, debe de ser',es:'Debes descansar. Deberías ir al médico. Debe de estar cansada.',en:'You must rest. You should see a doctor. She must be tired.',pb:'B1',pcic:['gramatica:12.1'],req:['g:conditional'],src:['gr-modalidad-b1','fn-aconsejar-b1'],note:'deber de = conjecture (formal); everyday speech often uses deber for both — accept both, teach the distinction.'},
// u36 Work and money (checkpoint)
{id:'g:passive-se',u:36,t:'Things done (who did it doesn\'t matter): se vendieron, se construyó, se firmarán',es:'Se vendieron todos los almuerzos. El edificio se construyó en 1920. Se firmará el lunes.',en:'All the lunches were sold. The building was built in 1920. It will be signed on Monday.',pb:'B1',pcic:['gramatica:7.1.4'],req:['g:se-impersonal'],src:['gr-se-multiuso-b1','gr-pronombre-personal-b2']},
{id:'g:comparatives-advanced',u:36,t:'Comparing in numbers and degrees: el doble, más de la mitad, cada vez más, cuanto más…',es:'Ganamos el doble que el año pasado. Cada vez hay más turistas. Cuanto más trabajo, menos duermo.',en:'We earn twice as much as last year. There are more and more tourists. The more I work, the less I sleep.',pb:'B1',pcic:['gramatica:2.5','gramatica:15.3.8'],req:['g:tanto-como'],src:['gr-comparativas-b1','gr-modificadores-adverbios-b1','nt-aumento-proporcion-grado-b1','nt-cantidad-numerica-relativa-b1']},
{id:'g:consequence-connectors',u:36,t:'So, therefore, so much that: por lo tanto, de modo que, tan… que',es:'Las ventas bajaron; por lo tanto, cerramos los lunes. Estaba tan cansado que se durmió.',en:'Sales fell; therefore we close on Mondays. He was so tired that he fell asleep.',pb:'B1',pcic:['gramatica:15.3.7'],req:['g:cause-result'],src:['gr-consecutivas-b1','dc-marcadores-discurso-b1']},
// u37 Keeping a conversation going
{id:'g:questions-prepositions',u:37,t:'Questions with a preposition first: ¿con quién?, ¿de qué?, ¿para qué?, ¿a qué hora?',es:'¿Con quién hablaste? ¿De qué se trata? ¿Para qué sirve esto?',en:'Who did you talk to? What\'s it about? What\'s this for?',pb:'B1',pcic:['gramatica:7.3'],req:['g:que-vs-cual'],src:['gr-interrogativos-b1','gr-orden-interrogativos-b2']},
{id:'g:reported-requests',u:37,t:'Passing on requests: dice que vengas, me pide que lo llame',es:'Vale dice que la llames. Mi mamá me pide que vaya el domingo. Dile que espere.',en:'Vale says to call her. My mom is asking me to go on Sunday. Tell him to wait.',pb:'B1',pcic:['tacticas_pragmaticas:1.5.2','gramatica:9.2.1'],req:['g:subj-influence','g:reported-past-basic'],src:['fn-pedir-ayuda-b1','fn-responder-orden-b1'],contrasts:['x:decir-que-ind-subj'],note:'decir que + indicative = report; + subjunctive = request.'},
{id:'g:indirect-questions',u:37,t:'Asking politely and reporting questions: ¿sabe si…?, no sé dónde…, quería saber cuándo…',es:'¿Sabe si está abierto? No sé dónde lo dejé. Quería saber cuánto cuesta.',en:'Do you know if it\'s open? I don\'t know where I left it. I wanted to know how much it costs.',pb:'B1',pcic:['gramatica:15.1.2'],req:['g:reported-past-basic','g:questions-prepositions'],src:['fn-pedir-informacion-b1','fn-conocimiento-desconocimiento-b1'],note:'Accent stays on the question word.'},
// u38 In the news
{id:'g:passive-ser',u:38,t:'The news voice: fue construido, serán juzgados, está prohibido',es:'El edificio fue declarado patrimonio. Los responsables serán investigados.',en:'The building was declared heritage. Those responsible will be investigated.',pb:'B2',pcic:['gramatica:12.1'],req:['g:passive-se','g:estar-participle'],src:['gr-nucleo-verbal-c1','gn-expositiva-b2'],contrasts:['x:ser-estar-participle'],note:'Mostly written/news; speech prefers se or ellos.'},
{id:'g:causal-advanced',u:38,t:'Giving causes in writing: ya que, puesto que, debido a, a causa de, por + verb',es:'Ya que estás aquí, ayúdame. Cerraron debido a la lluvia. La multaron por no tener permiso.',en:'Since you\'re here, help me. They closed because of the rain. They fined her for not having a permit.',pb:'B1',pcic:['gramatica:15.3.4'],req:['g:cause-result'],src:['gr-causales-b1','gr-sub-adv-causales-c1']},
{id:'g:concession-despite',u:38,t:'Despite: a pesar de, a pesar de que, sin embargo, aun así',es:'A pesar de la lluvia, vinieron. Es caro; sin embargo, vale la pena. Aun así, no firmo.',en:'Despite the rain, they came. It\'s expensive; however, it\'s worth it. Even so, I\'m not signing.',pb:'B1',pcic:['gramatica:15.3.9'],req:['g:aunque-indicative'],src:['gr-concesivas-b1','fn-contraargumento-b1','dc-marcadores-discurso-b1']},
// u39 Joining ideas / a longer text
{id:'g:infinitive-subject',u:39,t:'Doing things as subjects: fumar es malo, me encanta cocinar, el no saber',es:'Cocinar para tanta gente no es fácil. Me molesta tener que esperar.',en:'Cooking for so many people isn\'t easy. Having to wait bothers me.',pb:'B1',pcic:['gramatica:9.4.1'],req:['g:gustar-full','g:verb-infinitive'],src:['gr-formas-no-personales-b1','gr-sub-sustantivas-c1']},
{id:'g:discourse-structure',u:39,t:'Organising a text: en primer lugar, además, por un lado… por otro, en resumen',es:'En primer lugar, el local es nuestro. Además, el barrio nos apoya. En resumen, no vendemos.',en:'Firstly, the premises are ours. Besides, the neighbourhood supports us. In short, we\'re not selling.',pb:'B1',pcic:['tacticas_pragmaticas','generos_discursivos'],req:['g:consequence-connectors'],src:['dc-marcadores-discurso-b1','dc-estructuradores-a2','gn-composicion-escrita-b1','gn-exponer-tema-b1']},
{id:'g:referring-back',u:39,t:'Not repeating yourself in a text: este, ese, aquel, dicho, el mismo, lo anterior',es:'El alcalde y el concejal hablaron; este dijo que… Dicho proyecto fue aprobado.',en:'The mayor and the councillor spoke; the latter said… The said project was approved.',pb:'B1',pcic:['tacticas_pragmaticas'],req:['g:demonstratives'],src:['dc-mantenimiento-referente-b1','gr-demostrativos-valores-a2','dc-mantenimiento-referente-a2']},
// u40 If things were different (checkpoint)
{id:'g:imperfect-subj',u:40,t:'The "if only" forms: fuera, tuviera, pudiera (from the past form)',es:'Si tuviera plata, compraría el edificio. Ojalá pudiera ayudarte.',en:'If I had money, I\'d buy the building. I wish I could help you.',pb:'B2',pcic:['gramatica:9.2.2'],req:['g:preterite-spelling-stem','g:conditional','g:subj-wishes'],src:['impsubj','gr-impsubj-valores-b2'],note:'Built from ellos preterite (tuvieron → tuviera). -ra for production; -se recognised (g:se-form-recognition).'},
{id:'g:si-hypothetical',u:40,t:'If things were different: si fuera… sería…',es:'Si fuera tú, hablaría con ella. Si no lloviera, abriríamos la terraza.',en:'If I were you, I\'d talk to her. If it weren\'t raining, we\'d open the terrace.',pb:'B2',pcic:['gramatica:15.3.6'],req:['g:imperfect-subj','g:si-present'],src:['gr-condicionales-b1','task-b1-hipotesis'],contrasts:['x:si-real-unreal'],note:'Never conditional after si (*si tendría).'},
{id:'g:como-si',u:40,t:'As if: como si fuera, como si nada',es:'Habla como si fuera el dueño. Siguió como si nada.',en:'He talks as if he were the owner. She carried on as if nothing had happened.',pb:'B2',pcic:['gramatica:15.3.3'],req:['g:imperfect-subj'],src:['gr-subordinadas-modo-b2','gr-sub-adv-lugar-modo-c1']},
// u41 Wishes and regrets
{id:'g:subj-past-triggers',u:41,t:'Wanting, asking, feeling — in the past: quería que, me pidió que, me alegró que',es:'Quería que vinieras. Me pidió que la llamara. Me alegró que ganaran.',en:'I wanted you to come. She asked me to call her. I was glad they won.',pb:'B2',pcic:['gramatica:9.2.2'],req:['g:imperfect-subj','g:subj-influence'],src:['impsubj','gr-impsubj-valores-b2'],note:'Sequence of tenses: past trigger → -ra form.'},
{id:'g:ojala-past',u:41,t:'Wishing things were different: ojalá + fuera / tuviera',es:'Ojalá estuvieras aquí. Ojalá fuera tan fácil. Quisiera tener más tiempo.',en:'I wish you were here. If only it were that easy. I wish I had more time.',pb:'B2',pcic:['gramatica:9.2.2'],req:['g:imperfect-subj'],src:['fn-deseos-b2','fn-expresar-deseos-b1'],note:'ojalá + present (hope) vs + -ra (wish).'},
{id:'g:reported-commands-past',u:41,t:'Reporting orders and requests: me dijo que fuera, les pidió que esperaran',es:'Me dijo que fuera a la reunión. Les pidió que esperaran afuera.',en:'He told me to go to the meeting. She asked them to wait outside.',pb:'B2',pcic:['tacticas_pragmaticas:1.5.2'],req:['g:subj-past-triggers','g:reported-requests'],src:['dc-cita-b2','dc-estilo-indirecto-c1']},
// ---------------- B2 ----------------
// u42 One thing, five ways (register)
{id:'g:register-ladder',u:42,t:'Saying the same thing five ways: from "pásame eso" to "le agradecería que…"',es:'Pásame la sal. / ¿Me pasas la sal? / ¿Me podría pasar la sal? / Le agradecería que me enviara el documento.',en:'Pass me the salt. / Could you pass the salt? / Would you be so kind… / I would be grateful if you sent me the document.',pb:'B2',pcic:['tacticas_pragmaticas','funciones'],req:['g:subj-past-triggers','g:conditional'],src:['task-b2-registro','dc-atenuacion-b2','fn-pedir-ayuda-b2','fn-pedir-permiso-b2'],note:'Includes usted-to-tú negotiation and Colombian over-politeness (¿será que me puede…?).'},
{id:'g:softening',u:42,t:'Softening: quería pedirle, ¿será que…?, un poquito, me imagino que',es:'Quería preguntarle algo. ¿Será que me puede ayudar? Me imagino que está ocupado.',en:'I wanted to ask you something. Could you possibly help me? I imagine you\'re busy.',pb:'B2',pcic:['tacticas_pragmaticas:2'],req:['g:register-ladder'],src:['dc-atenuacion-b1','dc-atenuacion-1apersona-a2','dc-atenuacion-acto-indirecto-a2','dc-atenuacion-b2'],note:'Imperfect of politeness, future of softening (¿será que…?, very Colombian).'},
// u43 What would have happened
{id:'g:pluperfect-subj',u:43,t:'Had it happened: hubiera llegado, hubiéramos sabido',es:'Ojalá lo hubiera sabido. No creí que hubieran vendido.',en:'I wish I had known. I didn\'t believe they had sold.',pb:'B2',pcic:['gramatica:9.2.4'],req:['g:imperfect-subj','g:pluperfect'],src:['gr-pluscuamsubj-b2','gr-impsubj-valores-b2']},
{id:'g:conditional-perfect',u:43,t:'Would have: habría ido, lo habría hecho',es:'Yo habría dicho que no. ¿Qué habrías hecho tú?',en:'I would have said no. What would you have done?',pb:'B2',pcic:['gramatica:9.1.10'],req:['g:conditional','g:pluperfect'],src:['condperf','gr-condicional-compuesto-b2']},
{id:'g:si-past-unreal',u:43,t:'If it had happened: si hubiera sabido, habría venido (and mixed: hoy estaría…)',es:'Si hubiera sabido, habría venido antes. Si no hubiéramos firmado, hoy estaríamos tranquilos.',en:'If I had known, I would have come sooner. If we hadn\'t signed, we\'d be fine today.',pb:'B2',pcic:['gramatica:15.3.6'],req:['g:pluperfect-subj','g:conditional-perfect','g:si-hypothetical'],src:['task-b2-hipotesis','gr-sub-adv-condicionales-c1'],note:'Colloquial LatAm also uses hubiera… hubiera (si hubiera sabido, hubiera venido): accept it.'},
// u44 Making the case (checkpoint)
{id:'g:subj-concessive',u:44,t:'Even if: aunque llueva, por más que insista',es:'Aunque me ofrezcan un millón, no vendo. Por más que insista, no voy a firmar.',en:'Even if they offer me a million, I\'m not selling. However much he insists, I\'m not going to sign.',pb:'B2',pcic:['gramatica:15.3.9'],req:['g:aunque-indicative','g:subj-irregulars'],src:['gr-concesivas-b1','gr-sub-adv-concesivas-c1','fn-contraargumento-b1'],contrasts:['x:aunque-ind-subj']},
{id:'g:subj-conditions',u:44,t:'Only if, unless, in case: a menos que, con tal de que, siempre que, en caso de que',es:'Firmo con tal de que nos dejen quedarnos. No cerramos a menos que llueva. En caso de que llamen, avísame.',en:'I\'ll sign as long as they let us stay. We don\'t close unless it rains. In case they call, let me know.',pb:'B2',pcic:['gramatica:15.3.6'],req:['g:subj-concessive','g:si-present'],src:['gr-sub-adv-condicionales-c1','gr-condicionales-b1']},
{id:'g:argument-markers',u:44,t:'Building an argument: es cierto que…, pero; no solo… sino también; en cambio; de hecho',es:'Es cierto que necesitamos dinero, pero no a cualquier precio. De hecho, las ventas suben.',en:'It\'s true we need money, but not at any price. In fact, sales are going up.',pb:'B2',pcic:['tacticas_pragmaticas','generos_discursivos'],req:['g:discourse-structure','g:concession-despite'],src:['gn-argumentativa-b2','gn-composicion-argumentativa-b2','dc-marcadores-discurso-b2','task-b2-argumento']},
// u45 The news
{id:'g:future-perfect',u:45,t:'Guessing about what has happened: habrá salido, se habrán equivocado',es:'No contesta; se habrá dormido. Habrán llegado ya.',en:'He\'s not answering; he must have fallen asleep. They\'ll have arrived by now.',pb:'B2',pcic:['gramatica:9.1.9'],req:['g:future-conjecture','g:perfecto-experience'],src:['futperf','gr-futuro-perfecto-b2']},
{id:'g:conditional-rumour',u:45,t:'Reporting without vouching: según fuentes, el alcalde habría firmado',es:'Según el diario, la empresa habría pagado sobornos. El acusado estaría fuera del país.',en:'According to the paper, the company allegedly paid bribes. The accused is reportedly abroad.',pb:'C1',pcic:['gramatica:9.1.5','tacticas_pragmaticas'],req:['g:conditional-perfect'],src:['dc-citas-encubiertas-c1','fn-dar-informacion-b2','task-b2-noticia'],note:'Journalistic; recognise and use in reporting.'},
{id:'g:impersonal-register',u:45,t:'Who did it? Hiding the doer: dicen que, se cree que, uno, la gente',es:'Dicen que el alcalde renunció. Se cree que fue un error. Uno no puede saberlo todo.',en:'They say the mayor resigned. It\'s believed it was a mistake. One can\'t know everything.',pb:'B2',pcic:['gramatica:7.1.4'],req:['g:passive-ser','g:impersonal-obligation'],src:['gr-se-multiuso-b1','dc-citas-encubiertas-c1','nt-expresion-verbal-b2']},
// u46 Who said what
{id:'g:reported-speech-full',u:46,t:'Reporting a whole conversation: tenses, times and places shift',es:'"Mañana vengo" → Dijo que al día siguiente vendría. "¿Dónde está?" → Preguntó dónde estaba.',en:'"I\'ll come tomorrow" → He said he would come the next day. "Where is it?" → She asked where it was.',pb:'B2',pcic:['tacticas_pragmaticas:1.5.2'],req:['g:reported-commands-past','g:time-sequence','g:indirect-questions'],src:['dc-cita-b2','dc-estilo-indirecto-c1','dc-perspectiva-temporal-b2','task-b2-citar']},
{id:'g:reporting-verbs-mood',u:46,t:'Verbs that report and verbs that request: advertir que, recordar que, insistir en que',es:'Me advirtió que era peligroso. / Me advirtió que no fuera. Insistió en que pagáramos.',en:'He warned me it was dangerous. / He warned me not to go. She insisted that we pay.',pb:'B2',pcic:['gramatica:15.1.2','gramatica:9.2.2'],req:['g:reported-speech-full'],src:['gr-subordinadas-sustantivas-b2','nt-expresion-verbal-b2'],contrasts:['x:decir-que-ind-subj']},
{id:'g:subj-perception-negated',u:46,t:'Not seeing, not noticing, not saying: no vi que…, no dijo que…, no es que…',es:'No es que no quiera, es que no puedo. No noté que estuviera enojada.',en:'It\'s not that I don\'t want to, it\'s that I can\'t. I didn\'t notice she was angry.',pb:'B2',pcic:['gramatica:9.2.1','gramatica:9.2.2'],req:['g:subj-opinion-negated','g:imperfect-subj'],src:['gr-subordinadas-sustantivas-b2','gr-tiempos-subjuntivo-c1']},
// u47 Putting the weight where you want it
{id:'g:cleft-focus',u:47,t:'Putting the spotlight on one part: fue Vale quien…, lo que necesito es…, aquí es donde…',es:'Fue Vale quien encontró la carta. Lo que no entiendo es por qué. Es aquí donde todo empezó.',en:'It was Vale who found the letter. What I don\'t understand is why. This is where it all began.',pb:'B2',pcic:['tacticas_pragmaticas','gramatica:15.2'],req:['g:relatives-prepositions','g:lo-adjective'],src:['dc-focalizacion-b2','dc-focalizacion-b1','dc-rematizacion-tematizacion-b2']},
{id:'g:topic-fronting',u:47,t:'Starting with the topic: el contrato lo firmé yo; a Vale no le dije nada',es:'El contrato lo firmé yo. A Vale no le dije nada. Eso no lo sabía.',en:'I\'m the one who signed the contract. I didn\'t tell Vale anything. That I didn\'t know.',pb:'B2',pcic:['tacticas_pragmaticas','gramatica:13.2'],req:['g:le-doubling','g:direct-objects'],src:['dc-rematizacion-tematizacion-b2','dc-tematizacion-a2','gr-complementos-verbales-c1'],note:'A fronted object needs its pronoun.'},
{id:'g:lo-que-intensity',u:47,t:'How very…!: lo difícil que es, lo bien que cocina, con lo cansado que estoy',es:'No sabes lo difícil que es. ¡Lo bien que cocina tu mamá! Con lo cansado que estoy…',en:'You don\'t know how hard it is. How well your mom cooks! Tired as I am…',pb:'B2',pcic:['gramatica:3.1','gramatica:7.4'],req:['g:lo-adjective'],src:['gr-articulo-definido-valores-b2','gr-exclamativos-b2','dc-intensificacion-b2']},
// u48 Describing precisely (checkpoint)
{id:'g:relatives-formal',u:48,t:'Formal relatives: el cual, la cual, lo cual, quien(es)',es:'Firmaron un acuerdo, lo cual nos sorprendió. Su abuela, quien fundó el café, murió en 2019.',en:'They signed an agreement, which surprised us. His grandmother, who founded the café, died in 2019.',pb:'C1',pcic:['gramatica:7.2','gramatica:15.2'],req:['g:relatives-prepositions'],src:['gr-relativos-c1','gr-que-explicativo-b2','gr-subordinadas-relativas-tipos-b2','gr-quien-quienes-b2'],note:'Commas change meaning (explicativas).'},
{id:'g:participle-gerund-clauses',u:48,t:'Compact descriptions: una vez terminado, siendo tan tarde, construido en 1920',es:'Construido en 1920, el edificio es patrimonio. Siendo tan tarde, preferimos esperar.',en:'Built in 1920, the building is heritage. It being so late, we\'d rather wait.',pb:'B2',pcic:['gramatica:9.4.2','gramatica:9.4.3'],req:['g:passive-ser','g:gerund-ways'],src:['gr-formas-no-personales-b2','gr-formas-no-personales-c1'],note:'Avoid the "gerund of afterwards" (*Llegó, sentándose después).'},
{id:'g:infinitive-perfect',u:48,t:'Having done: después de haber firmado, por no haber llamado',es:'Después de haber firmado, se arrepintió. Me multaron por no haber pagado.',en:'After having signed, he regretted it. They fined me for not having paid.',pb:'B2',pcic:['gramatica:9.4.1'],req:['g:perfecto-experience','g:prep-infinitive'],src:['gr-formas-no-personales-b2']},
// u49 Formal writing
{id:'g:formal-letter-grammar',u:49,t:'Formal letters: le agradecería que, me dirijo a usted, adjunto le envío',es:'Me dirijo a ustedes para presentar una queja. Le agradecería que me respondiera antes del viernes.',en:'I am writing to you to make a complaint. I would be grateful if you replied before Friday.',pb:'B2',pcic:['generos_discursivos','gramatica:9.2.2'],req:['g:register-ladder'],src:['gn-carta-solicitud-trabajo-b2','gn-reclamacion-b2','gn-generos-escritos-b2','task-b2-formal']},
{id:'g:verbs-prepositions',u:49,t:'Verbs that bring their own preposition: contar con, depender de, tratarse de, consistir en',es:'Contamos con su apoyo. Depende de ti. Se trata de un error. Consiste en tres partes.',en:'We count on your support. It depends on you. It\'s a mistake. It consists of three parts.',pb:'B2',pcic:['gramatica:12.2.5'],req:['g:relatives-prepositions'],src:['gr-complemento-preposicional-regido-b2','gr-complementos-sa-b2'],note:'Grammar node for the principle; each verb is a pattern node.'},
// u50 Hard conversations
{id:'g:subj-free-relatives',u:50,t:'Whoever, wherever, whatever: el que quiera, donde quieras, lo que sea',es:'El que quiera venir, que venga. Siéntate donde quieras. Haré lo que sea necesario.',en:'Whoever wants to come can come. Sit wherever you like. I\'ll do whatever is necessary.',pb:'B2',pcic:['gramatica:15.2','gramatica:15.3.2'],req:['g:subj-relative'],src:['gr-subordinadas-lugar-b2','gr-subordinadas-modo-b2','gr-sub-adjetivas-relativo-c1']},
{id:'g:subj-future-in-past',u:50,t:'When it would happen: dijo que me llamaría cuando llegara',es:'Me dijo que me llamaría cuando llegara. Íbamos a esperar hasta que bajaran los precios.',en:'He said he would call me when he arrived. We were going to wait until prices fell.',pb:'B2',pcic:['gramatica:9.2.2','gramatica:15.3.1'],req:['g:subj-cuando-future','g:subj-past-triggers'],src:['gr-tiempos-subjuntivo-c1','gr-sub-adv-temporales-c1']},
{id:'g:que-wishes-commands',u:50,t:'Que + wish or order: que entre, que lo haga él, que no se repita',es:'—Está aquí el abogado. —Que entre. Que lo haga él. Que no vuelva a pasar.',en:'—The lawyer is here. —Show him in. Let him do it. Don\'t let it happen again.',pb:'B2',pcic:['gramatica:9.2.1','gramatica:9.3'],req:['g:subj-wishes','g:negative-commands'],src:['gr-imperativo-valores-b2','gr-imperativo-valores-b1','fn-ordenar-directo-b1']},
// u51 Spanish beyond Colombia
{id:'g:vosotros-recognition',u:51,t:'Reading Spain\'s Spanish: vosotros, habéis, id, os',es:'¿Vosotros qué queréis? Os lo dije. Venid mañana.',en:'What do you (all) want? I told you. Come tomorrow.',pb:'A1',pcic:['gramatica:7.1.1','gramatica:9.1.1'],req:['g:subj-irregulars','g:commands-tu'],src:['gr-pronombre-sujeto-a1','gr-pronombre-personal-c1'],note:'Recognition only. Learners keep producing ustedes; Peninsular answers are accepted everywhere.'},
{id:'g:spain-pasts',u:51,t:'Spain\'s "today" past: hoy he ido = hoy fui',es:'(España) Esta mañana he ido al médico. = (Colombia) Esta mañana fui al médico.',en:'This morning I went to the doctor.',pb:'C1',pcic:['gramatica:9.1.6'],req:['g:perfecto-experience','g:vosotros-recognition'],src:['gr-perfecto-vs-indefinido-a2','dc-indefinido-perfecto-c1'],note:'Recognition + accepted as answers; the Peninsular perfecto/indefinido split is explained, not produced.'},
{id:'g:se-form-recognition',u:51,t:'The other "if only" form: hubiese, fuese, tuviese',es:'Si lo hubiese sabido… = Si lo hubiera sabido…',en:'If I had known…',pb:'B2',pcic:['gramatica:9.2.2'],req:['g:pluperfect-subj'],src:['impsubj','gr-pluscuamsubj-b2'],note:'Recognition; -se is mostly written in LatAm.'},
// ---------------- C1 ----------------
// u52 The whole verb system (checkpoint)
{id:'g:tense-modal-uses',u:52,t:'Tenses that don\'t mean their time: quería pedirte, será caro pero…, mañana viajo',es:'Quería pedirte un favor. Será muy rico, pero no tiene modales. En 1810 se firma el acta.',en:'I wanted to ask you a favour. He may be rich, but he has no manners. In 1810 the act is signed.',pb:'C1',pcic:['gramatica:9.1','gramatica:9.1.2','gramatica:9.1.4'],req:['g:softening','g:future-perfect'],src:['gr-tiempos-indicativo-c1','dc-imperfecto-modal-c1','gr-presente-indicativo-valores-a1'],note:'Historic present, imperfect of politeness and of plans (iba a…), future of concession.'},
{id:'g:mood-choice-fine',u:52,t:'Choosing the mood on purpose: el hecho de que, lo que digas, como no vengas',es:'El hecho de que no llamara me preocupa. Haz lo que te digan. Como no vengas, me enojo.',en:'The fact that he didn\'t call worries me. Do what they tell you. If you don\'t come, I\'ll get angry.',pb:'C1',pcic:['gramatica:9.2','gramatica:15.1.2'],req:['g:subj-free-relatives','g:subj-concessive'],src:['gr-tiempos-subjuntivo-c1','gr-sub-sustantivas-c1','task-c1-verbos']},
// u53 Saying it without owning it
{id:'g:hedging-distance',u:53,t:'Distancing yourself from a claim: al parecer, supuestamente, por lo visto, no es que…',es:'Al parecer, el permiso era falso. Supuestamente iban a demoler. No es que dude de ti.',en:'Apparently the permit was fake. They were supposedly going to demolish. It\'s not that I doubt you.',pb:'C1',pcic:['tacticas_pragmaticas'],req:['g:conditional-rumour','g:subj-perception-negated'],src:['dc-citas-encubiertas-c1','dc-atenuacion-c1','dc-atenuacion-dialogica-c1','task-c1-decirlo']},
{id:'g:reformulation',u:53,t:'Saying it again, better: o sea, es decir, mejor dicho, en otras palabras',es:'Es caro; o sea, no lo podemos pagar. Mejor dicho: no queremos.',en:'It\'s expensive; I mean, we can\'t pay for it. Or rather: we don\'t want to.',pb:'C1',pcic:['tacticas_pragmaticas'],req:['g:discourse-structure'],src:['dc-reformuladores-c1','fn-escepticismo-contraargumento-c1']},
// u54 Irony and what\'s left unsaid
{id:'g:emphatic-structures',u:54,t:'Saying it with force: ¡si ya te lo dije!, ¡qué va!, ¡pues claro que sí!',es:'¡Si ya te lo dije! ¿Que si me gusta? ¡Me encanta! ¡Pues claro que voy!',en:'But I already told you! Do I like it? I love it! Of course I\'m going!',pb:'C1',pcic:['tacticas_pragmaticas','gramatica:13.3'],req:['g:si-present','g:indirect-questions'],src:['dc-intensificacion-c1','dc-valores-ilocutivos-c1','dc-ironia-c1','task-c1-ironia']},
{id:'g:wish-exclamatives',u:54,t:'Wishes and regrets as exclamations: ¡quién lo hubiera dicho!, ¡si lo hubiera sabido!',es:'¡Quién lo hubiera dicho! ¡Si al menos llamara! ¡Ojalá nunca lo hubiera firmado!',en:'Who would have thought it! If only he\'d call! I wish I\'d never signed it!',pb:'C1',pcic:['gramatica:7.4','gramatica:9.2.4'],req:['g:pluperfect-subj','g:ojala-past'],src:['gr-exclamativos-c1','fn-arrepentimiento-verguenza-c1','fn-sorpresa-admiracion-c1']},
// u55 Institutional Spanish
{id:'g:cuyo-relatives',u:55,t:'Whose: cuyo, cuya (and how people avoid it)',es:'El edificio, cuyos dueños viven en Miami, será vendido.',en:'The building, whose owners live in Miami, will be sold.',pb:'C1',pcic:['gramatica:2.1.3'],req:['g:relatives-formal'],src:['gr-clases-adjetivos-c1','gr-relativos-c1']},
{id:'g:nominalisation',u:55,t:'Turning actions into nouns: la firma del contrato, el cierre, la toma de decisiones',es:'Tras la firma del contrato, se anunció el cierre del local.',en:'After the contract was signed, the closure of the premises was announced.',pb:'C1',pcic:['gramatica:10.2','generos_discursivos'],req:['g:passive-ser','g:verbs-prepositions'],src:['gr-complementos-nominal-c1','gr-complementos-modificadores-b1','gr-complementos-nominales-b2','gn-carta-comercial-c1']},
{id:'g:absolute-constructions',u:55,t:'Once done: una vez firmado el contrato, terminada la reunión, dicho esto',es:'Una vez aprobado el plan, comenzarán las obras. Dicho esto, pasemos al siguiente punto.',en:'Once the plan is approved, work will begin. Having said that, let\'s move on.',pb:'C1',pcic:['gramatica:9.4.3'],req:['g:participle-gerund-clauses'],src:['gr-formas-no-personales-c1']},
// u56 The essay (checkpoint)
{id:'g:concessive-advanced',u:56,t:'Conceding like a writer: si bien, aun cuando, por mucho que, por muy… que',es:'Si bien el plan es ambicioso, es viable. Por muy rico que sea, no puede comprarlo todo.',en:'Although the plan is ambitious, it is feasible. However rich he may be, he can\'t buy everything.',pb:'C1',pcic:['gramatica:15.3.9'],req:['g:subj-concessive'],src:['gr-sub-adv-concesivas-c1','gn-argumentativa-c1','gn-argumentativa-conectores-c1']},
{id:'g:consecutive-advanced',u:56,t:'Results in writing: de ahí que, de manera que, así pues, por consiguiente',es:'No hubo acuerdo; de ahí que la reunión se aplazara. Así pues, la decisión es nuestra.',en:'There was no agreement; hence the meeting was postponed. Thus, the decision is ours.',pb:'C1',pcic:['gramatica:15.3.7'],req:['g:consequence-connectors','g:imperfect-subj'],src:['gr-sub-adv-consecutivas-c1','gn-expositiva-c1'],note:'de ahí que + subjunctive.'},
// u57 Emotion at native pitch
{id:'g:conditional-advanced',u:57,t:'Conditions with style: de haberlo sabido, como no llegues, a no ser que, siempre y cuando',es:'De haberlo sabido, no habría venido. Como no llegues a tiempo, nos vamos sin ti.',en:'Had I known, I wouldn\'t have come. If you\'re not on time, we\'re leaving without you.',pb:'C1',pcic:['gramatica:15.3.6'],req:['g:si-past-unreal','g:subj-conditions'],src:['gr-sub-adv-condicionales-c1','fn-hipotesis-posibilidad-c1']},
{id:'g:comparative-advanced-c1',u:57,t:'Fine comparisons: cuanto más… menos, ni que fuera, más vale que',es:'Cuanto más lo pienso, menos lo entiendo. ¡Ni que fuera el presidente! Más vale que llegues temprano.',en:'The more I think about it, the less I understand. As if he were the president! You\'d better get here early.',pb:'C1',pcic:['gramatica:15.3.8'],req:['g:comparatives-advanced','g:imperfect-subj'],src:['gr-sub-adv-comparativas-c1']},
// u58 Precision
{id:'g:temporal-advanced',u:58,t:'Exact timing: nada más llegar, apenas, en cuanto, una vez que, a medida que',es:'Nada más llegar, se fue la luz. A medida que avanzaba la noche, llegaba más gente.',en:'As soon as we arrived, the power went out. As the night went on, more people arrived.',pb:'C1',pcic:['gramatica:15.3.1'],req:['g:subj-cuando-future'],src:['gr-sub-adv-temporales-c1','nt-localizacion-presente-c1']},
{id:'g:agreement-tricky',u:58,t:'Agreement when sense beats grammar: la mayoría piensa(n), el resto, la gente',es:'La mayoría de los vecinos votó (votaron) en contra. Un grupo de turistas llegó.',en:'Most of the neighbours voted against. A group of tourists arrived.',pb:'C1',pcic:['gramatica:10.4','gramatica:13.1'],req:['g:adjective-agreement'],src:['gr-concordancia-oracional-c1','gr-concordancia-sn-verbo-b2']},
{id:'g:ser-estar-c1',u:58,t:'Ser and estar at the edges: está de mesero, es de madera, estar para / estar por',es:'Ahora está de mesero en Cartagena. Está para llover. Eso está por verse.',en:'He\'s working as a waiter in Cartagena now. It\'s about to rain. That remains to be seen.',pb:'C1',pcic:['gramatica:12.1'],req:['g:ser-estar-adjectives','g:passive-ser'],src:['gr-nucleo-verbal-c1','ser-estar','gr-ser-estar-adjetivos-a2'],contrasts:['x:ser-estar-adj']},
// u59 Voices of Colombia
{id:'g:voseo-recognition',u:59,t:'Hearing paisas (and Argentines): vos tenés, vos sabés, vení',es:'¿Vos qué querés? Vení, sentate. ¿Sabés qué?',en:'What do you want? Come, sit down. You know what?',pb:'C1',pcic:['gramatica:7.1.1','referentes_culturales'],req:['g:vosotros-recognition','g:commands-tu'],src:['gr-pronombre-personal-c1'],note:'Recognition only (Medellín story dialogue); never required in production. Also usted among family in Bogotá/Boyacá.'},
{id:'g:future-subj-recognition',u:59,t:'Old and legal Spanish: quien hiciere, si así fuere',es:'El que no cumpliere será sancionado. Adonde fueres, haz lo que vieres.',en:'Whoever fails to comply will be penalised. When in Rome, do as the Romans do.',pb:'C1',pcic:['gramatica:9.2.5'],req:['g:subj-free-relatives'],src:['gr-tiempos-subjuntivo-c1'],note:'Recognition only (legal texts, proverbs).'},
// u60 A critical voice (checkpoint)
{id:'g:word-order-style',u:60,t:'Word order for effect: Mucho ha cambiado el barrio; poco importa ya',es:'Mucho ha cambiado el barrio desde entonces. Difícil es decirlo. Poco importa ya.',en:'The neighbourhood has changed a lot since then. It\'s hard to say. It hardly matters now.',pb:'C1',pcic:['gramatica:13.2','tacticas_pragmaticas'],req:['g:topic-fronting','g:cleft-focus'],src:['dc-rematizacion-tematizacion-c1','dc-focalizacion-c1','gr-adverbios-nucleares-c1','gr-adverbios-externos-c1']},
{id:'g:evaluative-adverbs',u:60,t:'Commenting on your own sentence: lamentablemente, francamente, por suerte, sinceramente',es:'Lamentablemente, el café cerró. Francamente, no me sorprende. Por suerte, nadie salió herido.',en:'Sadly, the café closed. Frankly, I\'m not surprised. Luckily, nobody was hurt.',pb:'B2',pcic:['gramatica:8.3','gramatica:8.4'],req:['g:adverbs-mente'],src:['gr-adverbios-evaluativos-b2','gr-adverbios-enunciacion-b2','gr-adverbios-externos-c1','gr-adverbios-conjuntivos-c1'],note:'Placed with the critical-review unit where it does most work.'},
];
